// [S4] Three-portal family features — family join requests.
enum JoinRequestStatus {
  pending,
  accepted,
  declined,
  cancelled,
  unknown;

  static JoinRequestStatus fromApi(String? value) => switch (value) {
    'Pending' => JoinRequestStatus.pending,
    'Accepted' => JoinRequestStatus.accepted,
    'Declined' => JoinRequestStatus.declined,
    'Cancelled' => JoinRequestStatus.cancelled,
    _ => JoinRequestStatus.unknown,
  };

  String get friendlyLabel => switch (this) {
    JoinRequestStatus.pending => 'Waiting for approval',
    JoinRequestStatus.accepted => 'Approved',
    JoinRequestStatus.declined => 'Declined',
    JoinRequestStatus.cancelled => 'Cancelled',
    JoinRequestStatus.unknown => 'Status unavailable',
  };
}

class JoinRequest {
  const JoinRequest({
    required this.id,
    required this.familyId,
    required this.relationshipType,
    required this.status,
    required this.createdAt,
    this.familyName,
    this.requesterDisplayName,
    this.requesterEmailMasked,
    this.message,
    this.respondedAt,
  });

  factory JoinRequest.fromJson(Map<String, dynamic> json) => JoinRequest(
    id: json['id'] as String,
    familyId: json['familyId'] as String,
    familyName: json['familyName'] as String?,
    requesterDisplayName: json['requesterDisplayName'] as String?,
    requesterEmailMasked: json['requesterEmailMasked'] as String?,
    relationshipType: (json['relationshipType'] as String?) ?? 'Member',
    message: json['message'] as String?,
    status: JoinRequestStatus.fromApi(json['status'] as String?),
    createdAt: DateTime.parse(json['createdAt'] as String),
    respondedAt: json['respondedAt'] == null
        ? null
        : DateTime.parse(json['respondedAt'] as String),
  );

  final String id;
  final String familyId;
  final String? familyName;
  final String? requesterDisplayName;
  final String? requesterEmailMasked;
  final String relationshipType;
  final String? message;
  final JoinRequestStatus status;
  final DateTime createdAt;
  final DateTime? respondedAt;
}
